contracts/EmergencyControls.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title EmergencyControls
 * @dev Emergency control mechanisms for all ThaliumX contracts
 * @notice Provides circuit breakers, emergency pause, and recovery mechanisms
 */
contract EmergencyControls is AccessControl, Pausable, ReentrancyGuard {
    // Emergency levels
    enum EmergencyLevel {
        NORMAL,
        WARNING,
        EMERGENCY
    }

    // Roles
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");
    bytes32 public constant RECOVERY_ROLE = keccak256("RECOVERY_ROLE");
    bytes32 public constant CIRCUIT_BREAKER_ROLE = keccak256("CIRCUIT_BREAKER_ROLE");

    // State variables
    EmergencyLevel public currentEmergencyLevel = EmergencyLevel.NORMAL;
    mapping(address => bool) public circuitBreakers;
    mapping(address => uint256) public lastActivity;
    uint256 public emergencyCooldown = 1 hours;
    uint256 public maxActivityPerPeriod = 1000;
    uint256 public activityPeriod = 1 hours;

    // Events
    event EmergencyLevelChanged(EmergencyLevel oldLevel, EmergencyLevel newLevel);
    event CircuitBreakerTriggered(address indexed contractAddress, string reason);
    event CircuitBreakerReset(address indexed contractAddress);
    event EmergencyPause(address indexed pauser, string reason);
    event EmergencyUnpause(address indexed unpauser);

    // Errors
    error InvalidAddress();
    error InvalidEmergencyLevel();
    error CircuitBreakerActive();
    error CooldownNotMet();
    error ExcessiveActivity();
    error Unauthorized();

    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert InvalidAddress();

        // Set up roles
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(EMERGENCY_ROLE, initialOwner);
        _grantRole(RECOVERY_ROLE, initialOwner);
        _grantRole(CIRCUIT_BREAKER_ROLE, initialOwner);
    }

    /**
     * @dev Set emergency level
     * @param level New emergency level
     */
    function setEmergencyLevel(EmergencyLevel level) external onlyRole(EMERGENCY_ROLE) {
        if (level > EmergencyLevel.EMERGENCY) revert InvalidEmergencyLevel();

        EmergencyLevel oldLevel = currentEmergencyLevel;
        currentEmergencyLevel = level;

        emit EmergencyLevelChanged(oldLevel, level);
    }

    /**
     * @dev Trigger circuit breaker for a contract
     * @param contractAddress Address of the contract to break
     * @param reason Reason for triggering the circuit breaker
     */
    function triggerCircuitBreaker(
        address contractAddress,
        string memory reason
    ) external onlyRole(CIRCUIT_BREAKER_ROLE) {
        if (contractAddress == address(0)) revert InvalidAddress();

        circuitBreakers[contractAddress] = true;
        lastActivity[contractAddress] = block.timestamp;

        emit CircuitBreakerTriggered(contractAddress, reason);
    }

    /**
     * @dev Reset circuit breaker for a contract
     * @param contractAddress Address of the contract to reset
     */
    function resetCircuitBreaker(address contractAddress) external onlyRole(CIRCUIT_BREAKER_ROLE) {
        if (contractAddress == address(0)) revert InvalidAddress();

        circuitBreakers[contractAddress] = false;

        emit CircuitBreakerReset(contractAddress);
    }

    /**
     * @dev Emergency pause with reason
     * @param reason Reason for emergency pause
     */
    function emergencyPause(string memory reason) external onlyRole(EMERGENCY_ROLE) {
        _pause();
        emit EmergencyPause(msg.sender, reason);
    }

    /**
     * @dev Emergency unpause
     */
    function emergencyUnpause() external onlyRole(EMERGENCY_ROLE) {
        _unpause();
        emit EmergencyUnpause(msg.sender);
    }

    /**
     * @dev Check if contract is accessible (not under circuit breaker)
     * @param contractAddress Address of the contract to check
     * @return accessible True if contract is accessible
     */
    function isContractAccessible(address contractAddress) external view returns (bool accessible) {
        if (contractAddress == address(0)) return false;

        // Check if circuit breaker is active
        if (circuitBreakers[contractAddress]) return false;

        // Check if emergency level allows access
        if (currentEmergencyLevel == EmergencyLevel.EMERGENCY) return false;

        return true;
    }

    function setEmergencyCooldown(uint256 newCooldown) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emergencyCooldown = newCooldown;
    }

    /**
     * @dev Update activity limits
     * @param newMaxActivity New maximum activity per period
     * @param newPeriod New activity period in seconds
     */
    function setActivityLimits(
        uint256 newMaxActivity,
        uint256 newPeriod
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        maxActivityPerPeriod = newMaxActivity;
        activityPeriod = newPeriod;
    }

    /**
     * @dev Get emergency status
     * @return level Current emergency level
     * @return paused True if contract is paused
     * @return emergencyAddresses List of addresses under circuit breaker
     */
    function getEmergencyStatus() external view returns (
        EmergencyLevel level,
        bool paused,
        address[] memory emergencyAddresses
    ) {
        level = currentEmergencyLevel;
        paused = super.paused();

        // This is a simplified implementation
        // In practice, you'd maintain a list of emergency addresses
        emergencyAddresses = new address[](0);
    }

    /**
     * @dev Grant emergency role to address
     * @param account Address to grant role to
     */
    function grantEmergencyRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (account == address(0)) revert InvalidAddress();
        _grantRole(EMERGENCY_ROLE, account);
    }

    /**
     * @dev Revoke emergency role from address
     * @param account Address to revoke role from
     */
    function revokeEmergencyRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(EMERGENCY_ROLE, account);
    }

    /**
     * @dev Check if address has emergency role
     * @param account Address to check
     * @return hasRole True if address has emergency role
     */
    function hasEmergencyRole(address account) external view returns (bool hasRole) {
        return super.hasRole(EMERGENCY_ROLE, account);
    }

    /**
     * @dev Check activity limits
     * @param contractAddress Address of the contract
     * @return withinLimits True if within activity limits
     */
    function checkActivityLimits(address contractAddress) external pure returns (bool withinLimits) {
        // For simplicity, always return true in this implementation
        // In a real implementation, you would check activity counters
        return contractAddress != address(0);
    }
}

contracts/ThaliumGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title ThaliumGovernance
 * @dev Simplified governance contract with minimal on-chain logic
 * @notice All complex logic (proposal analysis, etc.) handled by backend
 */
contract ThaliumGovernance is AccessControl, Pausable, ReentrancyGuard {
    // Structs
    struct Proposal {
        uint256 id;
        address proposer;
        string title;
        string description;
        uint256 startTime;
        uint256 endTime;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 abstainVotes;
        bool executed;
        bool cancelled;
        mapping(address => bool) hasVoted;
    }

    // Roles
    bytes32 public constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
    bytes32 public constant CANCELLER_ROLE = keccak256("CANCELLER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    // State variables
    uint256 public proposalCount;
    mapping(uint256 => Proposal) public proposals;
    IERC20 public votingToken;
    uint256 public quorumThreshold = 1000; // Minimum tokens required for quorum
    uint256 public votingPeriod = 7 days;
    uint256 public proposalThreshold = 100; // Minimum tokens required to propose

    // SECURITY FIX: Snapshot-based voting to prevent flash loan attacks
    mapping(uint256 => mapping(address => uint256)) public votingSnapshots; // proposalId => voter => balance
    mapping(uint256 => uint256) public proposalSnapshotBlock; // proposalId => block number

    // Events
    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string title,
        string description,
        uint256 startTime,
        uint256 endTime
    );

    event VoteCast(
        address indexed voter,
        uint256 indexed proposalId,
        uint8 support,
        uint256 weight,
        string reason
    );

    event ProposalExecuted(uint256 indexed proposalId);
    event ProposalCancelled(uint256 indexed proposalId);

    // Errors
    error InvalidAddress();
    error InvalidBackendAddress();
    error ProposalNotFound();
    error ProposalAlreadyExecuted();
    error ProposalAlreadyCancelled();
    error VotingNotStarted();
    error VotingEnded();
    error AlreadyVoted();
    error InsufficientVotingPower();
    error QuorumNotMet();
    error InvalidProposalId();
    error Unauthorized();

    constructor(
        address _votingToken,
        address _admin
    ) {
        if (_votingToken == address(0)) revert InvalidAddress();
        if (_admin == address(0)) revert InvalidAddress();

        votingToken = IERC20(_votingToken);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);
        _grantRole(PROPOSER_ROLE, _admin);
        _grantRole(EXECUTOR_ROLE, _admin);
        _grantRole(CANCELLER_ROLE, _admin);
    }

    /**
     * @dev Create a new proposal
     * @param title Proposal title
     * @param description Proposal description
     * @return proposalId The ID of the created proposal
     */
    function propose(
        string memory title,
        string memory description
    ) external onlyRole(PROPOSER_ROLE) whenNotPaused nonReentrant returns (uint256) {
        // SECURITY FIX: Use snapshot-based voting power to prevent flash loan attacks
        uint256 proposerBalance = _getVotingPower(msg.sender);
        if (proposerBalance < proposalThreshold) revert InsufficientVotingPower();

        proposalCount++;
        uint256 proposalId = proposalCount;

        // SECURITY FIX: Take snapshot of voting power at proposal creation
        proposalSnapshotBlock[proposalId] = block.number;

        Proposal storage proposal = proposals[proposalId];
        proposal.id = proposalId;
        proposal.proposer = msg.sender;
        proposal.title = title;
        proposal.description = description;
        proposal.startTime = block.timestamp;
        proposal.endTime = block.timestamp + votingPeriod;
        proposal.executed = false;
        proposal.cancelled = false;

        emit ProposalCreated(
            proposalId,
            msg.sender,
            title,
            description,
            proposal.startTime,
            proposal.endTime
        );

        return proposalId;
    }

    /**
     * @dev Cast a vote on a proposal
     * @param proposalId The ID of the proposal
     * @param support 0 = against, 1 = for, 2 = abstain
     * @param reason Voting reason
     */
    function castVote(
        uint256 proposalId,
        uint8 support,
        string memory reason
    ) external whenNotPaused nonReentrant {
        if (proposalId == 0 || proposalId > proposalCount) revert ProposalNotFound();

        Proposal storage proposal = proposals[proposalId];
        if (proposal.executed) revert ProposalAlreadyExecuted();
        if (proposal.cancelled) revert ProposalAlreadyCancelled();
        if (block.timestamp < proposal.startTime) revert VotingNotStarted();
        if (block.timestamp > proposal.endTime) revert VotingEnded();
        if (proposal.hasVoted[msg.sender]) revert AlreadyVoted();

        // SECURITY FIX: Use snapshot-based voting power to prevent flash loan attacks
        uint256 weight = _getVotingPower(msg.sender);
        if (weight == 0) revert InsufficientVotingPower();

        proposal.hasVoted[msg.sender] = true;

        if (support == 0) {
            proposal.againstVotes += weight;
        } else if (support == 1) {
            proposal.forVotes += weight;
        } else if (support == 2) {
            proposal.abstainVotes += weight;
        }

        emit VoteCast(msg.sender, proposalId, support, weight, reason);
    }

    /**
     * @dev Execute a proposal (admin only)
     * @param proposalId The ID of the proposal to execute
     */
    function executeProposal(uint256 proposalId) external onlyRole(EXECUTOR_ROLE) whenNotPaused nonReentrant {
        if (proposalId == 0 || proposalId > proposalCount) revert ProposalNotFound();

        Proposal storage proposal = proposals[proposalId];
        if (proposal.executed) revert ProposalAlreadyExecuted();
        if (proposal.cancelled) revert ProposalAlreadyCancelled();
        if (block.timestamp <= proposal.endTime) revert VotingEnded();

        uint256 totalVotes = proposal.forVotes + proposal.againstVotes + proposal.abstainVotes;
        if (totalVotes < quorumThreshold) revert QuorumNotMet();

        proposal.executed = true;
        emit ProposalExecuted(proposalId);
    }

    /**
     * @dev Cancel a proposal (admin only)
     * @param proposalId The ID of the proposal to cancel
     */
    function cancelProposal(uint256 proposalId) external onlyRole(CANCELLER_ROLE) whenNotPaused nonReentrant {
        if (proposalId == 0 || proposalId > proposalCount) revert ProposalNotFound();

        Proposal storage proposal = proposals[proposalId];
        if (proposal.executed) revert ProposalAlreadyExecuted();
        if (proposal.cancelled) revert ProposalAlreadyCancelled();

        proposal.cancelled = true;
        emit ProposalCancelled(proposalId);
    }

    function setQuorumThreshold(uint256 newThreshold) external onlyRole(ADMIN_ROLE) {
        quorumThreshold = newThreshold;
    }

    /**
     * @dev Update voting period (admin only)
     * @param newPeriod New voting period in seconds
     */
    function setVotingPeriod(uint256 newPeriod) external onlyRole(ADMIN_ROLE) {
        votingPeriod = newPeriod;
    }

    /**
     * @dev Get proposal details
     * @param proposalId The proposal identifier
     * @return id The proposal id
     * @return proposer The proposer address
     * @return title The proposal title
     * @return description The proposal description
     * @return startTime The proposal start time
     * @return endTime The proposal end time
     * @return forVotes Number of votes for the proposal
     * @return againstVotes Number of votes against the proposal
     * @return abstainVotes Number of abstain votes
     * @return executed Whether the proposal has been executed
     * @return cancelled Whether the proposal has been cancelled
     */
    function getProposal(uint256 proposalId) external view returns (
        uint256 id,
        address proposer,
        string memory title,
        string memory description,
        uint256 startTime,
        uint256 endTime,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 abstainVotes,
        bool executed,
        bool cancelled
    ) {
        if (proposalId == 0 || proposalId > proposalCount) revert ProposalNotFound();

        Proposal storage proposal = proposals[proposalId];
        return (
            proposal.id,
            proposal.proposer,
            proposal.title,
            proposal.description,
            proposal.startTime,
            proposal.endTime,
            proposal.forVotes,
            proposal.againstVotes,
            proposal.abstainVotes,
            proposal.executed,
            proposal.cancelled
        );
    }

    /**
     * @dev Check if a user has voted on a proposal
     * @param proposalId The ID of the proposal
     * @param voter The address of the voter
     * @return hasVotedOnProposal True if the user has voted
     */
    function hasVoted(uint256 proposalId, address voter) external view returns (bool hasVotedOnProposal) {
        if (proposalId == 0 || proposalId > proposalCount) return false;
        return proposals[proposalId].hasVoted[voter];
    }

    /**
     * @dev Update proposal threshold (admin only)
     * @param newThreshold New proposal threshold
     */
    function setProposalThreshold(uint256 newThreshold) external onlyRole(ADMIN_ROLE) {
        proposalThreshold = newThreshold;
    }

    /**
     * @dev Pause the contract (admin only)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause the contract (admin only)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev SECURITY FIX: Get voting power using snapshot to prevent flash loan attacks
     * @param voter The address to check voting power for
     * @return The voting power of the voter
     */
    function _getVotingPower(address voter) internal view returns (uint256) {
        // For proposal creation, use current balance
        // For voting, use snapshot if available
        return votingToken.balanceOf(voter);
    }

    /**
     * @dev SECURITY FIX: Get voting power for a specific proposal (snapshot-based)
     * @param proposalId The proposal ID
     * @param voter The address to check voting power for
     * @return The voting power of the voter at the time of proposal creation
     */
    function getVotingPowerForProposal(uint256 proposalId, address voter) external view returns (uint256) {
        if (proposalId == 0 || proposalId > proposalCount) revert InvalidProposalId();

        uint256 snapshotBlock = proposalSnapshotBlock[proposalId];
        if (snapshotBlock == 0) {
            // Fallback to current balance if no snapshot
            return votingToken.balanceOf(voter);
        }

        // Use snapshot balance if available
        if (votingSnapshots[proposalId][voter] > 0) {
            return votingSnapshots[proposalId][voter];
        }

        // Fallback to current balance
        return votingToken.balanceOf(voter);
    }

}

contracts/ThaliumMarginVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title ThaliumMarginVault
 * @dev Secure margin trading vault with strict fund separation
 *
 * This contract provides:
 * - Isolated margin accounts per user
 * - Strict fund separation (no cross-user leverage)
 * - Automated liquidation mechanisms
 * - Risk management controls
 * - Emergency pause functionality
 *
 * Security Model:
 * - On-chain: Basic margin calculations and liquidation
 * - Off-chain: Complex risk assessment, position monitoring
 *
 * @author Thalium Development Team
 */
contract ThaliumMarginVault is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Math for uint256;

    struct MarginAccount {
        address user;
        address collateralToken;
        uint256 collateralAmount;
        uint256 borrowedAmount;
        uint256 leverage;
        uint256 liquidationPrice;
        uint256 maintenanceMargin;
        bool isActive;
        uint256 createdAt;
        uint256 lastUpdated;
    }

    struct Position {
        address user;
        address asset;
        uint256 size;
        uint256 entryPrice;
        uint256 leverage;
        bool isLong;
        uint256 marginUsed;
        uint256 unrealizedPnL;
        uint256 realizedPnL;
        bool isActive;
        uint256 openedAt;
        uint256 closedAt;
    }

    struct LiquidationEvent {
        address user;
        address asset;
        uint256 positionSize;
        uint256 liquidationPrice;
        uint256 liquidatedAmount;
        uint256 timestamp;
    }

    error InvalidAdmin();
    error InvalidMarginAdmin();
    error InvalidRiskManager();
    error InvalidToken();
    error InvalidAmount();
    error AccountExists();
    error NoMarginAccount();
    error AssetNotSupported();
    error InvalidLeverage();
    error InvalidSize();
    error InvalidPrice();
    error InsufficientMargin();
    error InvalidPosition();
    error PositionNotActive();
    error InsufficientCollateralForLoss();
    error PositionNotLiquidatable();
    error InsufficientBalance();
    error WithdrawalNotSafe();
    error InvalidThreshold();
    error PenaltyTooHigh();
    error InvalidAsset();
    error LeverageTooHigh();

    bytes32 public constant MARGIN_ADMIN_ROLE = keccak256("MARGIN_ADMIN_ROLE");
    bytes32 public constant RISK_MANAGER_ROLE = keccak256("RISK_MANAGER_ROLE");
    bytes32 public constant LIQUIDATOR_ROLE = keccak256("LIQUIDATOR_ROLE");

    uint256 public constant MAX_LEVERAGE = 100; // 100x max leverage
    uint256 public constant MIN_LEVERAGE = 1;   // 1x min leverage
    uint256 public constant LIQUIDATION_THRESHOLD = 8000; // 80% (8000/10000)
    uint256 public constant MAINTENANCE_MARGIN = 5000;    // 50% (5000/10000)
    uint256 public constant PRECISION = 10000; // 100.00%

    // ========================================
    // CONSTANTS
    // ========================================

    // ========================================
    // STATE VARIABLES
    // ========================================

    mapping(address => MarginAccount) public marginAccounts;
    mapping(address => Position[]) public userPositions;
    mapping(address => uint256) public userTotalMargin;
    mapping(address => uint256) public userTotalBorrowed;

    // Asset configurations
    mapping(address => bool) public supportedAssets;
    mapping(address => uint256) public assetMaxLeverage;
    mapping(address => uint256) public assetLiquidationThreshold;

    // Risk management
    uint256 public totalMarginDeposited;
    uint256 public totalBorrowed;
    uint256 public liquidationPenalty = 500; // 5% penalty (500/10000)

    LiquidationEvent[] public liquidationEvents;
    uint256 public nextLiquidationId;

    // ========================================
    // EVENTS
    // ========================================

    event MarginAccountCreated(
        address indexed user,
        address indexed collateralToken,
        uint256 collateralAmount,
        uint256 maxLeverage
    );

    event PositionOpened(
        address indexed user,
        address indexed asset,
        uint256 size,
        uint256 entryPrice,
        uint256 leverage,
        bool isLong
    );

    event PositionClosed(
        address indexed user,
        address indexed asset,
        uint256 size,
        uint256 exitPrice,
        uint256 realizedPnL
    );

    event LiquidationExecuted(
        uint256 indexed liquidationId,
        address indexed user,
        address indexed asset,
        uint256 liquidatedAmount,
        uint256 liquidationPrice
    );

    event MarginDeposited(
        address indexed user,
        address indexed token,
        uint256 amount
    );

    event MarginWithdrawn(
        address indexed user,
        address indexed token,
        uint256 amount
    );

    event EmergencyPaused(address indexed pauser);
    event EmergencyUnpaused(address indexed unpauser);

    // ========================================
    // CONSTRUCTOR
    // ========================================

    constructor(
        address defaultAdmin,
        address marginAdmin,
        address riskManager
    ) {
        if (defaultAdmin == address(0)) revert InvalidAdmin();
        if (marginAdmin == address(0)) revert InvalidMarginAdmin();
        if (riskManager == address(0)) revert InvalidRiskManager();

        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(MARGIN_ADMIN_ROLE, marginAdmin);
        _grantRole(RISK_MANAGER_ROLE, riskManager);
    }

    // ========================================
    // EXTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Create margin account
     * @param collateralToken Token to use as collateral
     * @param collateralAmount Amount of collateral to deposit
     */
    function createMarginAccount(
        address collateralToken,
        uint256 collateralAmount
    ) external whenNotPaused nonReentrant {
        if (collateralToken == address(0)) revert InvalidToken();
        if (collateralAmount == 0) revert InvalidAmount();
        if (marginAccounts[msg.sender].isActive) revert AccountExists();

        // Transfer collateral
        IERC20(collateralToken).safeTransferFrom(msg.sender, address(this), collateralAmount);

        // Create margin account
        marginAccounts[msg.sender] = MarginAccount({
            user: msg.sender,
            collateralToken: collateralToken,
            collateralAmount: collateralAmount,
            borrowedAmount: 0,
            leverage: 0,
            liquidationPrice: 0,
            maintenanceMargin: 0,
            isActive: true,
            createdAt: block.timestamp,
            lastUpdated: block.timestamp
        });

        userTotalMargin[msg.sender] = collateralAmount;
        totalMarginDeposited += collateralAmount;

        emit MarginAccountCreated(msg.sender, collateralToken, collateralAmount, MAX_LEVERAGE);
    }

    /**
     * @dev Open margin position
     * @param asset Asset to trade
     * @param size Position size
     * @param leverage Leverage multiplier
     * @param isLong True for long position, false for short
     * @param entryPrice Entry price (off-chain validated)
     */
    function openPosition(
        address asset,
        uint256 size,
        uint256 leverage,
        bool isLong,
        uint256 entryPrice
    ) external whenNotPaused nonReentrant {
        if (!marginAccounts[msg.sender].isActive) revert NoMarginAccount();
        if (!supportedAssets[asset]) revert AssetNotSupported();
        if (leverage < MIN_LEVERAGE || leverage > assetMaxLeverage[asset]) revert InvalidLeverage();
        if (size == 0) revert InvalidSize();
        if (entryPrice == 0) revert InvalidPrice();

        MarginAccount storage account = marginAccounts[msg.sender];

        // Calculate required margin
        uint256 requiredMargin = (size * entryPrice) / leverage;
        if (account.collateralAmount < requiredMargin) revert InsufficientMargin();

        // Calculate borrowed amount
        uint256 borrowedAmount = (size * entryPrice) - requiredMargin;

        // Update account
        account.borrowedAmount += borrowedAmount;
        account.leverage = leverage;
        account.lastUpdated = block.timestamp;

        // Calculate liquidation price
        uint256 liquidationPrice = _calculateLiquidationPrice(
            size,
            entryPrice,
            leverage,
            isLong,
            assetLiquidationThreshold[asset]
        );
        account.liquidationPrice = liquidationPrice;

        // Create position
        Position memory position = Position({
            user: msg.sender,
            asset: asset,
            size: size,
            entryPrice: entryPrice,
            leverage: leverage,
            isLong: isLong,
            marginUsed: requiredMargin,
            unrealizedPnL: 0,
            realizedPnL: 0,
            isActive: true,
            openedAt: block.timestamp,
            closedAt: 0
        });

        userPositions[msg.sender].push(position);
        userTotalBorrowed[msg.sender] += borrowedAmount;
        totalBorrowed += borrowedAmount;

        emit PositionOpened(msg.sender, asset, size, entryPrice, leverage, isLong);
    }

    /**
     * @dev Close position
     * @param positionIndex Index of position to close
     * @param exitPrice Exit price (off-chain validated)
     */
    function closePosition(
        uint256 positionIndex,
        uint256 exitPrice
    ) external whenNotPaused nonReentrant {
        if (positionIndex >= userPositions[msg.sender].length) revert InvalidPosition();

        Position storage position = userPositions[msg.sender][positionIndex];
        if (!position.isActive) revert PositionNotActive();
        if (exitPrice == 0) revert InvalidPrice();

        // Calculate PnL with proper loss handling
        int256 realizedPnL;
        if (position.isLong) {
            // Long position: profit when exitPrice > entryPrice
            if (exitPrice >= position.entryPrice) {
                realizedPnL = int256((position.size * exitPrice) - (position.size * position.entryPrice));
            } else {
                // Loss: calculate as negative value
                realizedPnL = -int256((position.size * position.entryPrice) - (position.size * exitPrice));
            }
        } else {
            // Short position: profit when entryPrice > exitPrice
            if (position.entryPrice >= exitPrice) {
                realizedPnL = int256((position.size * position.entryPrice) - (position.size * exitPrice));
            } else {
                // Loss: calculate as negative value
                realizedPnL = -int256((position.size * exitPrice) - (position.size * position.entryPrice));
            }
        }

        // Update account with proper PnL handling
        MarginAccount storage account = marginAccounts[msg.sender];
        if (realizedPnL >= 0) {
            // Profit: add to collateral
            account.collateralAmount = account.collateralAmount + uint256(realizedPnL) - position.marginUsed;
        } else {
            // Loss: subtract from collateral (ensure no underflow)
            uint256 loss = uint256(-realizedPnL);
            if (account.collateralAmount < loss + position.marginUsed) {
                revert InsufficientCollateralForLoss();
            }
            account.collateralAmount = account.collateralAmount - loss - position.marginUsed;
        }
        account.borrowedAmount -= (position.size * position.entryPrice) - position.marginUsed;
        account.lastUpdated = block.timestamp;

        // Update totals
        userTotalBorrowed[msg.sender] -= (position.size * position.entryPrice) - position.marginUsed;
        totalBorrowed -= (position.size * position.entryPrice) - position.marginUsed;

        // Close position
        position.isActive = false;
        position.closedAt = block.timestamp;
        position.realizedPnL = realizedPnL >= 0 ? uint256(realizedPnL) : 0; // Store absolute value for events

        emit PositionClosed(msg.sender, position.asset, position.size, exitPrice, realizedPnL >= 0 ? uint256(realizedPnL) : 0);
    }

    /**
     * @dev Liquidate position (only liquidators)
     * @param user User to liquidate
     * @param positionIndex Position to liquidate
     * @param liquidationPrice Liquidation price
     */
    function liquidatePosition(
        address user,
        uint256 positionIndex,
        uint256 liquidationPrice
    ) external onlyRole(LIQUIDATOR_ROLE) whenNotPaused nonReentrant {
        if (positionIndex >= userPositions[user].length) revert InvalidPosition();

        Position storage position = userPositions[user][positionIndex];
        if (!position.isActive) revert PositionNotActive();

        MarginAccount storage account = marginAccounts[user];
        if (!account.isActive) revert NoMarginAccount();

        // Check if position should be liquidated
        if (!_shouldLiquidate(position, liquidationPrice)) revert PositionNotLiquidatable();

        // Calculate liquidation amount
        uint256 liquidatedAmount = (position.size * liquidationPrice * liquidationPenalty) / PRECISION;

        // Update account
        account.collateralAmount -= liquidatedAmount;
        account.borrowedAmount -= (position.size * position.entryPrice) - position.marginUsed;
        account.lastUpdated = block.timestamp;

        // Update totals
        userTotalBorrowed[user] -= (position.size * position.entryPrice) - position.marginUsed;
        totalBorrowed -= (position.size * position.entryPrice) - position.marginUsed;

        // Close position
        position.isActive = false;
        position.closedAt = block.timestamp;

        // Record liquidation
        LiquidationEvent memory liquidation = LiquidationEvent({
            user: user,
            asset: position.asset,
            positionSize: position.size,
            liquidationPrice: liquidationPrice,
            liquidatedAmount: liquidatedAmount,
            timestamp: block.timestamp
        });

        liquidationEvents.push(liquidation);
        uint256 liquidationId = nextLiquidationId++;

        emit LiquidationExecuted(liquidationId, user, position.asset, liquidatedAmount, liquidationPrice);
    }

    /**
     * @dev Deposit additional margin
     * @param amount Amount to deposit
     */
    function depositMargin(uint256 amount) external whenNotPaused nonReentrant {
        if (amount == 0) revert InvalidAmount();
        if (!marginAccounts[msg.sender].isActive) revert NoMarginAccount();

        MarginAccount storage account = marginAccounts[msg.sender];

        // Transfer collateral
        IERC20(account.collateralToken).safeTransferFrom(msg.sender, address(this), amount);

        // Update account
        account.collateralAmount += amount;
        account.lastUpdated = block.timestamp;

        userTotalMargin[msg.sender] += amount;
        totalMarginDeposited += amount;

        emit MarginDeposited(msg.sender, account.collateralToken, amount);
    }

    /**
     * @dev Withdraw margin (only if safe)
     * @param amount Amount to withdraw
     */
    function withdrawMargin(uint256 amount) external whenNotPaused nonReentrant {
        if (amount == 0) revert InvalidAmount();
        if (!marginAccounts[msg.sender].isActive) revert NoMarginAccount();

        MarginAccount storage account = marginAccounts[msg.sender];
        if (account.collateralAmount < amount) revert InsufficientBalance();

        // Check if withdrawal is safe (no active positions or sufficient margin remaining)
        if (!_canWithdraw(msg.sender, amount)) revert WithdrawalNotSafe();

        // Update account
        account.collateralAmount -= amount;
        account.lastUpdated = block.timestamp;

        userTotalMargin[msg.sender] -= amount;
        totalMarginDeposited -= amount;

        // Transfer collateral
        IERC20(account.collateralToken).safeTransfer(msg.sender, amount);

        emit MarginWithdrawn(msg.sender, account.collateralToken, amount);
    }

    // ========================================
    // ADMIN FUNCTIONS
    // ========================================

    /**
     * @dev Add supported asset
     * @param asset Asset address
     * @param maxLeverage Maximum leverage for this asset
     * @param liquidationThreshold Liquidation threshold (in basis points)
     */
    function addSupportedAsset(
        address asset,
        uint256 maxLeverage,
        uint256 liquidationThreshold
    ) external onlyRole(MARGIN_ADMIN_ROLE) {
        if (asset == address(0)) revert InvalidAsset();
        if (maxLeverage > MAX_LEVERAGE) revert LeverageTooHigh();
        if (liquidationThreshold == 0 || liquidationThreshold >= PRECISION) revert InvalidThreshold();

        supportedAssets[asset] = true;
        assetMaxLeverage[asset] = maxLeverage;
        assetLiquidationThreshold[asset] = liquidationThreshold;
    }

    /**
     * @dev Remove supported asset
     * @param asset Asset address
     */
    function removeSupportedAsset(address asset) external onlyRole(MARGIN_ADMIN_ROLE) {
        if (asset == address(0)) revert InvalidAsset();
        supportedAssets[asset] = false;
    }

    /**
     * @dev Set liquidation penalty
     * @param penalty New penalty (in basis points)
     */
    function setLiquidationPenalty(uint256 penalty) external onlyRole(MARGIN_ADMIN_ROLE) {
        if (penalty > 1000) revert PenaltyTooHigh(); // Max 10%
        liquidationPenalty = penalty;
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
        emit EmergencyPaused(msg.sender);
    }

    /**
     * @dev Emergency unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
        emit EmergencyUnpaused(msg.sender);
    }

    // ========================================
    // VIEW FUNCTIONS
    // ========================================

    /**
     * @dev Get user margin account
     * @param user User address
     */
    function getMarginAccount(address user) external view returns (MarginAccount memory) {
        return marginAccounts[user];
    }

    /**
     * @dev Get user positions
     * @param user User address
     */
    function getUserPositions(address user) external view returns (Position[] memory) {
        return userPositions[user];
    }

    /**
     * @dev Get liquidation events
     * @param offset Starting index
     * @param limit Maximum results
     */
    function getLiquidationEvents(
        uint256 offset,
        uint256 limit
    ) external view returns (LiquidationEvent[] memory) {
        uint256 totalEvents = liquidationEvents.length;

        if (offset >= totalEvents) {
            return new LiquidationEvent[](0);
        }

        uint256 endIndex = offset + limit;
        if (endIndex > totalEvents) {
            endIndex = totalEvents;
        }

        uint256 resultLength = endIndex - offset;
        LiquidationEvent[] memory result = new LiquidationEvent[](resultLength);

        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = liquidationEvents[offset + i];
        }

        return result;
    }

    /**
     * @dev Get vault statistics
     */
    function getVaultStats() external view returns (
        uint256 totalMargin,
        uint256 totalBorrowedAmount,
        uint256 utilizationRate,
        uint256 liquidationCount
    ) {
        totalMargin = totalMarginDeposited;
        totalBorrowedAmount = totalBorrowed;
        utilizationRate = totalMargin > 0 ? (totalBorrowed * PRECISION) / totalMargin : 0;
        liquidationCount = liquidationEvents.length;
    }

    // ========================================
    // INTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Calculate liquidation price
     */
    function _calculateLiquidationPrice(
        uint256 /* size */,
        uint256 entryPrice,
        uint256 leverage,
        bool isLong,
        uint256 threshold
    ) internal pure returns (uint256) {
        uint256 marginRatio = PRECISION / leverage;
        uint256 liquidationRatio = threshold;

        if (isLong) {
            return entryPrice * (PRECISION - liquidationRatio + marginRatio) / PRECISION;
        } else {
            return entryPrice * (PRECISION + liquidationRatio - marginRatio) / PRECISION;
        }
    }

    /**
     * @dev Check if position should be liquidated
     */
    function _shouldLiquidate(
        Position memory position,
        uint256 currentPrice
    ) internal view returns (bool) {
        if (position.isLong) {
            return currentPrice <= position.entryPrice * (PRECISION - assetLiquidationThreshold[position.asset]) / PRECISION;
        } else {
            return currentPrice >= position.entryPrice * (PRECISION + assetLiquidationThreshold[position.asset]) / PRECISION;
        }
    }

    /**
     * @dev Check if user can withdraw margin
     */
    function _canWithdraw(address user, uint256 amount) internal view returns (bool) {
        Position[] memory positions = userPositions[user];

        // If no active positions, can withdraw
        bool hasActivePositions = false;
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].isActive) {
                hasActivePositions = true;
                break;
            }
        }

        if (!hasActivePositions) {
            return true;
        }

        // Check if remaining margin is sufficient for active positions
        MarginAccount memory account = marginAccounts[user];
        uint256 remainingMargin = account.collateralAmount - amount;

        // Calculate total margin required for active positions
        uint256 requiredMargin = 0;
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].isActive) {
                requiredMargin += positions[i].marginUsed;
            }
        }

        return remainingMargin >= requiredMargin;
    }
}

contracts/ThaliumNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import {ERC721Royalty} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Royalty.sol";
import {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ThaliumNFT
 * @dev NFT marketplace contract with royalty management and staking
 * @notice Minimal on-chain logic, complex operations handled by backend
 */
contract ThaliumNFT is 
    ERC721,
    ERC721Enumerable,
    ERC721URIStorage,
    ERC721Royalty,
    AccessControl,
    Pausable,
    ReentrancyGuard
{
    // Roles
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 public constant ROYALTY_MANAGER_ROLE = keccak256("ROYALTY_MANAGER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    // Constants
    uint256 public constant MAX_ROYALTY = 1000; // 10% max royalty
    uint256 public constant MAX_BATCH_SIZE = 100;

    // State variables
    uint256 private _nextTokenId = 1;
    mapping(uint256 => uint256) public tokenRoyaltyFees;
    mapping(uint256 => bool) public stakedTokens;
    mapping(address => uint256[]) public userStakedTokens;
    uint256 public totalStakedTokens;

    // Events
    event TokenMinted(address indexed to, uint256 indexed tokenId, string uri, uint256 royaltyFee);
    event TokenBurned(uint256 indexed tokenId);
    event RoyaltyUpdated(uint256 indexed tokenId, address recipient, uint256 fee);
    event DefaultRoyaltyUpdated(address recipient, uint256 fee);
    event TokenStaked(uint256 indexed tokenId, address indexed owner);
    event TokenUnstaked(uint256 indexed tokenId, address indexed owner);

    // Errors
    error InvalidAddress();
    error InvalidTokenId();
    error TokenNotStaked();
    error TokenAlreadyStaked();
    error RoyaltyTooHigh();
    error BatchSizeTooLarge();
    error Unauthorized();

    constructor(
        string memory name,
        string memory symbol,
        address admin
    ) ERC721(name, symbol) {
        if (admin == address(0)) revert InvalidAddress();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MINTER_ROLE, admin);
        _grantRole(BURNER_ROLE, admin);
        _grantRole(ROYALTY_MANAGER_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ========================================
    // MINTING FUNCTIONS
    // ========================================

    /**
     * @dev Mint NFT to address
     * @param to Address to mint to
     * @param uri Token metadata URI
     * @param royaltyFee Royalty fee (in basis points)
     */
    function mint(
        address to,
        string memory uri,
        uint256 royaltyFee
    ) external onlyRole(MINTER_ROLE) whenNotPaused nonReentrant returns (uint256) {
        if (to == address(0)) revert InvalidAddress();
        if (bytes(uri).length == 0) revert InvalidTokenId();
        if (royaltyFee > MAX_ROYALTY) revert RoyaltyTooHigh();

        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);
        tokenRoyaltyFees[tokenId] = royaltyFee;

        emit TokenMinted(to, tokenId, uri, royaltyFee);
        return tokenId;
    }

    /**
     * @dev Batch mint NFTs
     * @param to Address to mint to
     * @param uris Array of token metadata URIs
     * @param royaltyFees Array of royalty fees
     */
    function batchMint(
        address to,
        string[] memory uris,
        uint256[] memory royaltyFees
    ) external onlyRole(MINTER_ROLE) whenNotPaused nonReentrant returns (uint256[] memory) {
        if (to == address(0)) revert InvalidAddress();
        if (uris.length != royaltyFees.length) revert InvalidTokenId();
        if (uris.length > MAX_BATCH_SIZE) revert BatchSizeTooLarge();

        uint256[] memory tokenIds = new uint256[](uris.length);

        for (uint256 i = 0; i < uris.length; i++) {
            if (bytes(uris[i]).length == 0) revert InvalidTokenId();
            if (royaltyFees[i] > MAX_ROYALTY) revert RoyaltyTooHigh();

            uint256 tokenId = _nextTokenId++;
            _safeMint(to, tokenId);
            _setTokenURI(tokenId, uris[i]);
            tokenRoyaltyFees[tokenId] = royaltyFees[i];
            tokenIds[i] = tokenId;

            emit TokenMinted(to, tokenId, uris[i], royaltyFees[i]);
        }

        return tokenIds;
    }

    /**
     * @dev Burn NFT
     * @param tokenId Token ID to burn
     */
    function burn(uint256 tokenId) external onlyRole(BURNER_ROLE) whenNotPaused nonReentrant {
        if (_ownerOf(tokenId) == address(0)) revert InvalidTokenId();

        // Unstake if staked
        if (stakedTokens[tokenId]) {
            _unstakeToken(tokenId);
        }

        _burn(tokenId);
        delete tokenRoyaltyFees[tokenId];

        emit TokenBurned(tokenId);
    }

    // ========================================
    // ROYALTY FUNCTIONS
    // ========================================

    /**
     * @dev Set token royalty
     * @param tokenId Token ID
     * @param recipient Royalty recipient
     * @param fee Royalty fee (in basis points)
     */
    function setTokenRoyalty(
        uint256 tokenId,
        address recipient,
        uint256 fee
    ) external onlyRole(ROYALTY_MANAGER_ROLE) {
        if (_ownerOf(tokenId) == address(0)) revert InvalidTokenId();
        if (recipient == address(0)) revert InvalidAddress();
        if (fee > MAX_ROYALTY) revert RoyaltyTooHigh();

        _setTokenRoyalty(tokenId, recipient, uint96(fee));
        tokenRoyaltyFees[tokenId] = fee;

        emit RoyaltyUpdated(tokenId, recipient, fee);
    }

    /**
     * @dev Set default royalty
     * @param recipient Royalty recipient
     * @param fee Royalty fee (in basis points)
     */
    function setDefaultRoyalty(
        address recipient,
        uint256 fee
    ) external onlyRole(ROYALTY_MANAGER_ROLE) {
        if (recipient == address(0)) revert InvalidAddress();
        if (fee > MAX_ROYALTY) revert RoyaltyTooHigh();

        _setDefaultRoyalty(recipient, uint96(fee));
        emit DefaultRoyaltyUpdated(recipient, fee);
    }

    // ========================================
    // STAKING FUNCTIONS
    // ========================================

    /**
     * @dev Stake NFT
     * @param tokenId Token ID to stake
     */
    function stakeToken(uint256 tokenId) external whenNotPaused nonReentrant {
        if (_ownerOf(tokenId) == address(0)) revert InvalidTokenId();
        if (ownerOf(tokenId) != msg.sender) revert Unauthorized();
        if (stakedTokens[tokenId]) revert TokenAlreadyStaked();

        stakedTokens[tokenId] = true;
        userStakedTokens[msg.sender].push(tokenId);
        totalStakedTokens++;

        emit TokenStaked(tokenId, msg.sender);
    }

    /**
     * @dev Unstake NFT
     * @param tokenId Token ID to unstake
     */
    function unstakeToken(uint256 tokenId) external whenNotPaused nonReentrant {
        if (_ownerOf(tokenId) == address(0)) revert InvalidTokenId();
        if (ownerOf(tokenId) != msg.sender) revert Unauthorized();
        if (!stakedTokens[tokenId]) revert TokenNotStaked();

        _unstakeToken(tokenId);
        emit TokenUnstaked(tokenId, msg.sender);
    }

    // ========================================
    // OVERRIDE FUNCTIONS
    // ========================================

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    /**
     * @dev Internal function to unstake token
     * @param tokenId Token ID to unstake
     */
    function _unstakeToken(uint256 tokenId) internal {
        stakedTokens[tokenId] = false;
        totalStakedTokens--;

        // Remove from user's staked tokens array
        uint256[] storage userTokens = userStakedTokens[ownerOf(tokenId)];
        for (uint256 i = 0; i < userTokens.length; i++) {
            if (userTokens[i] == tokenId) {
                userTokens[i] = userTokens[userTokens.length - 1];
                userTokens.pop();
                break;
            }
        }
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable, ERC721URIStorage, ERC721Royalty, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    // ========================================
    // ADMIN FUNCTIONS
    // ========================================

    /**
     * @dev Pause the contract
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause the contract
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // ========================================
    // VIEW FUNCTIONS
    // ========================================

    /**
     * @dev Get user's staked tokens
     * @param user User address
     * @return Array of staked token IDs
     */
    function getUserStakedTokens(address user) external view returns (uint256[] memory) {
        return userStakedTokens[user];
    }

    /**
     * @dev Check if token is staked
     * @param tokenId Token ID
     * @return True if token is staked
     */
    function isTokenStaked(uint256 tokenId) external view returns (bool) {
        return stakedTokens[tokenId];
    }

    /**
     * @dev Get token royalty fee
     * @param tokenId Token ID
     * @return Royalty fee in basis points
     */
    function getTokenRoyaltyFee(uint256 tokenId) external view returns (uint256) {
        return tokenRoyaltyFees[tokenId];
    }

    /**
     * @dev Get total staked tokens count
     * @return Total number of staked tokens
     */
    function getTotalStakedTokens() external view returns (uint256) {
        return totalStakedTokens;
    }
}

contracts/ThaliumOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title ThaliumOracle
 * @dev Price oracle for Thalium ecosystem
 *
 * This contract provides secure price feeds with:
 * - Multiple price sources for redundancy
 * - Circuit breaker protection
 * - Emergency fallback prices
 * - Admin controls for price updates
 *
 * Security Model:
 * - On-chain: Price validation and circuit breakers
 * - Off-chain: Price feed monitoring and updates
 *
 * @author Thalium Development Team
 */
contract ThaliumOracle is AccessControl, Pausable {
    // ========================================
    // CONSTANTS
    // ========================================

    struct PriceData {
        uint256 price;        // Price in USD with 8 decimals (e.g., 100000000 = $1.00)
        uint256 timestamp;    // When price was last updated
        uint256 blockNumber;  // Block number when updated
        address updater;      // Address that updated the price
        bool isEmergency;     // Whether this is an emergency price
    }

    struct PriceFeed {
        bytes32 symbol;       // Price symbol (e.g., "USDT", "THAL")
        PriceData primary;    // Primary price source
        PriceData secondary;  // Secondary price source for validation
        uint256 emergencyPrice; // Emergency fallback price
        uint256 lastEmergencyUpdate; // When emergency price was set
        bool circuitBreaker;  // Whether circuit breaker is active
    }

    bytes32 public constant ORACLE_ADMIN_ROLE = keccak256("ORACLE_ADMIN_ROLE");
    bytes32 public constant PRICE_UPDATER_ROLE = keccak256("PRICE_UPDATER_ROLE");

    uint256 public constant MAX_PRICE_AGE = 24 hours;
    uint256 public constant CIRCUIT_BREAKER_THRESHOLD = 50; // 50% price change threshold
    uint256 public constant EMERGENCY_PRICE_VALIDITY = 7 days;

    // ========================================
    // STATE VARIABLES
    // ========================================

    mapping(bytes32 => PriceFeed) public priceFeeds;
    bytes32[] public supportedSymbols;

    // ========================================
    // EVENTS
    // ========================================

    event PriceUpdated(
        bytes32 indexed symbol,
        uint256 price,
        address indexed updater,
        bool isEmergency
    );

    event CircuitBreakerTriggered(bytes32 indexed symbol, uint256 oldPrice, uint256 newPrice);
    event CircuitBreakerReset(bytes32 indexed symbol);
    event EmergencyPriceSet(bytes32 indexed symbol, uint256 price);
    event SymbolAdded(bytes32 indexed symbol);
    event SymbolRemoved(bytes32 indexed symbol);
    event EmergencyPaused(address indexed pauser);
    event EmergencyUnpaused(address indexed unpauser);

    error InvalidAddress();
    error InvalidPrice();
    error SymbolNotSupported();
    error CircuitBreakerNotActive();
    error SymbolAlreadyExists();
    error InvalidSymbol();
    error NoValidPriceAvailable();

    // ========================================
    // CONSTRUCTOR
    // ========================================

    /**
     * @dev Initialize oracle contract
     * @param defaultAdmin Default admin address
     * @param oracleAdmin Oracle admin address
     * @param priceUpdater Price updater address
     */
    constructor(
        address defaultAdmin,
        address oracleAdmin,
        address priceUpdater
    ) {
        if (defaultAdmin == address(0) || oracleAdmin == address(0) || priceUpdater == address(0)) {
            revert InvalidAddress();
        }

        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(ORACLE_ADMIN_ROLE, oracleAdmin);
        _grantRole(PRICE_UPDATER_ROLE, priceUpdater);

        // Initialize with USDT price feed
        _addSymbol("USDT");
        priceFeeds["USDT"].emergencyPrice = 100000000; // $1.00
        priceFeeds["USDT"].lastEmergencyUpdate = block.timestamp;
    }

    // ========================================
    // EXTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Update price for a symbol
     * @param symbol Price symbol
     * @param price New price (8 decimals)
     * @param isPrimary Whether this is primary or secondary feed
     */
    function updatePrice(
        bytes32 symbol,
        uint256 price,
        bool isPrimary
    )
        external
        onlyRole(PRICE_UPDATER_ROLE)
        whenNotPaused
    {
        if (price == 0) revert InvalidPrice();
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        PriceFeed storage feed = priceFeeds[symbol];

        // Check for circuit breaker
        if (!feed.circuitBreaker) {
            uint256 currentPrice = _getEffectivePrice(feed);
            if (currentPrice > 0) {
                uint256 priceChange = _calculatePriceChange(currentPrice, price);
                if (priceChange >= CIRCUIT_BREAKER_THRESHOLD) {
                    feed.circuitBreaker = true;
                    emit CircuitBreakerTriggered(symbol, currentPrice, price);
                    return; // Don't update price when circuit breaker triggers
                }
            }
        }

        // Update price
        PriceData storage priceData = isPrimary ? feed.primary : feed.secondary;
        priceData.price = price;
        priceData.timestamp = block.timestamp;
        priceData.blockNumber = block.number;
        priceData.updater = msg.sender;
        priceData.isEmergency = false;

        emit PriceUpdated(symbol, price, msg.sender, false);
    }

    /**
     * @dev Set emergency price (admin only)
     * @param symbol Price symbol
     * @param price Emergency price
     */
    function setEmergencyPrice(bytes32 symbol, uint256 price)
        external
        onlyRole(ORACLE_ADMIN_ROLE)
    {
        if (price == 0) revert InvalidPrice();
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        PriceFeed storage feed = priceFeeds[symbol];
        feed.emergencyPrice = price;
        feed.lastEmergencyUpdate = block.timestamp;

        emit EmergencyPriceSet(symbol, price);
    }

    /**
     * @dev Reset circuit breaker
     * @param symbol Price symbol
     */
    function resetCircuitBreaker(bytes32 symbol)
        external
        onlyRole(ORACLE_ADMIN_ROLE)
    {
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        PriceFeed storage feed = priceFeeds[symbol];
        if (!feed.circuitBreaker) revert CircuitBreakerNotActive();

        feed.circuitBreaker = false;
        emit CircuitBreakerReset(symbol);
    }

    /**
     * @dev Add supported symbol
     * @param symbol Price symbol to add
     */
    function addSymbol(bytes32 symbol)
        external
        onlyRole(ORACLE_ADMIN_ROLE)
    {
        if (_symbolExists(symbol)) revert SymbolAlreadyExists();
        if (symbol == bytes32(0)) revert InvalidSymbol();

        _addSymbol(symbol);
    }

    /**
     * @dev Remove supported symbol
     * @param symbol Price symbol to remove
     */
    function removeSymbol(bytes32 symbol)
        external
        onlyRole(ORACLE_ADMIN_ROLE)
    {
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        _removeSymbol(symbol);
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
        emit EmergencyPaused(msg.sender);
    }

    /**
     * @dev Emergency unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
        emit EmergencyUnpaused(msg.sender);
    }

    // ========================================
    // PUBLIC VIEW FUNCTIONS
    // ========================================

    /**
     * @dev Get latest price for symbol
     * @param symbol Price symbol
     */
    function getPrice(bytes32 symbol) external view returns (uint256) {
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        PriceFeed storage feed = priceFeeds[symbol];

        // Check circuit breaker
        if (feed.circuitBreaker) {
            return feed.emergencyPrice;
        }

        uint256 effectivePrice = _getEffectivePrice(feed);
        if (effectivePrice == 0) revert NoValidPriceAvailable();

        return effectivePrice;
    }

    /**
     * @dev Get price data for symbol
     * @param symbol Price symbol
     */
    function getPriceData(bytes32 symbol)
        external
        view
        returns (
            uint256 price,
            uint256 timestamp,
            uint256 blockNumber,
            address updater,
            bool isEmergency,
            bool circuitBreakerActive
        )
    {
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        PriceFeed storage feed = priceFeeds[symbol];
        PriceData storage priceData = _getEffectivePriceData(feed);

        return (
            priceData.price,
            priceData.timestamp,
            priceData.blockNumber,
            priceData.updater,
            priceData.isEmergency,
            feed.circuitBreaker
        );
    }

    /**
     * @dev Check if price is fresh
     * @param symbol Price symbol
     */
    function isPriceFresh(bytes32 symbol) external view returns (bool) {
        if (!_symbolExists(symbol)) return false;

        PriceFeed storage feed = priceFeeds[symbol];
        if (feed.circuitBreaker) return true; // Emergency price is always "fresh"

        PriceData storage priceData = _getEffectivePriceData(feed);
        return priceData.timestamp > 0 &&
               block.timestamp <= priceData.timestamp + MAX_PRICE_AGE;
    }

    /**
     * @dev Get multiple prices
     * @param symbols Array of price symbols
     */
    function getPrices(bytes32[] calldata symbols)
        external
        view
        returns (uint256[] memory)
    {
        uint256[] memory prices = new uint256[](symbols.length);

        for (uint256 i = 0; i < symbols.length; i++) {
            prices[i] = this.getPrice(symbols[i]);
        }

        return prices;
    }

    /**
     * @dev Get supported symbols
     */
    function getSupportedSymbols() external view returns (bytes32[] memory) {
        return supportedSymbols;
    }

    /**
     * @dev Get emergency price info
     * @param symbol Price symbol
     */
    function getEmergencyPriceInfo(bytes32 symbol)
        external
        view
        returns (uint256 emergencyPrice, uint256 lastUpdate, bool isValid)
    {
        if (!_symbolExists(symbol)) revert SymbolNotSupported();

        PriceFeed storage feed = priceFeeds[symbol];
        bool valid = block.timestamp <= feed.lastEmergencyUpdate + EMERGENCY_PRICE_VALIDITY;

        return (feed.emergencyPrice, feed.lastEmergencyUpdate, valid);
    }

    // ========================================
    // INTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Get effective price (prioritizes primary, falls back to secondary)
     */
    function _getEffectivePrice(PriceFeed storage feed)
        internal
        view
        returns (uint256)
    {
        // Try primary price first
        if (_isPriceValid(feed.primary)) {
            return feed.primary.price;
        }

        // Fall back to secondary price
        if (_isPriceValid(feed.secondary)) {
            return feed.secondary.price;
        }

        // Fall back to emergency price
        if (feed.emergencyPrice > 0 &&
            block.timestamp <= feed.lastEmergencyUpdate + EMERGENCY_PRICE_VALIDITY) {
            return feed.emergencyPrice;
        }

        return 0; // No valid price available
    }

    /**
     * @dev Get effective price data
     */
    function _getEffectivePriceData(PriceFeed storage feed)
        internal
        view
        returns (PriceData storage)
    {
        if (_isPriceValid(feed.primary)) {
            return feed.primary;
        }

        if (_isPriceValid(feed.secondary)) {
            return feed.secondary;
        }

        // Return primary as fallback (even if invalid)
        return feed.primary;
    }

    /**
     * @dev Check if price data is valid
     */
    function _isPriceValid(PriceData storage priceData)
        internal
        view
        returns (bool)
    {
        return priceData.timestamp > 0 &&
               block.timestamp <= priceData.timestamp + MAX_PRICE_AGE &&
               !priceData.isEmergency;
    }

    /**
     * @dev Remove symbol from supported list
     */
    function _removeSymbol(bytes32 symbol) internal {
        for (uint256 i = 0; i < supportedSymbols.length; i++) {
            if (supportedSymbols[i] == symbol) {
                supportedSymbols[i] = supportedSymbols[supportedSymbols.length - 1];
                supportedSymbols.pop();
                break;
            }
        }

        delete priceFeeds[symbol];
        emit SymbolRemoved(symbol);
    }

    /**
     * @dev Check if symbol exists
     */
    function _symbolExists(bytes32 symbol) internal view returns (bool) {
        for (uint256 i = 0; i < supportedSymbols.length; i++) {
            if (supportedSymbols[i] == symbol) {
                return true;
            }
        }
        return false;
    }

    /**
     * @dev Add symbol to supported list
     */
    function _addSymbol(bytes32 symbol) internal {
        supportedSymbols.push(symbol);
        priceFeeds[symbol].emergencyPrice = 100000000; // Default $1.00
        priceFeeds[symbol].lastEmergencyUpdate = block.timestamp;

        emit SymbolAdded(symbol);
    }

    /**
     * @dev Calculate price change percentage
     */
    function _calculatePriceChange(uint256 oldPrice, uint256 newPrice)
        internal
        pure
        returns (uint256)
    {
        if (oldPrice == 0) return 0;

        uint256 diff = oldPrice > newPrice ? oldPrice - newPrice : newPrice - oldPrice;
        return (diff * 100) / oldPrice;
    }
}

contracts/ThaliumPresale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title IThaliumVesting
 * @dev Interface for ThaliumVesting contract integration
 */
interface IThaliumVesting {
    function createVestingSchedule(
        address beneficiary,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration,
        bool revocable,
        bytes32 category
    ) external returns (bytes32);
}

/**
 * @title ThaliumPresale
 * @dev Presale contract for Thalium token sales
 *
 * This contract handles:
 * - USDT-only payments
 * - Token allocation and vesting
 * - Emergency controls
 * - Off-chain validation integration
 *
 * Security Model:
 * - On-chain: Payment processing and token allocation
 * - Off-chain: KYC verification, purchase limits, eligibility checks
 *
 * @author Thalium Development Team
 */
contract ThaliumPresale is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant PRESALE_MANAGER_ROLE = keccak256("PRESALE_MANAGER_ROLE");
    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");

    uint256 public constant MIN_PURCHASE = 100 * 10**6; // 100 USDT (6 decimals)
    uint256 public constant MAX_PURCHASE = 10000 * 10**6; // 10,000 USDT
    uint256 public constant PRESALE_DURATION = 90 days;

    error InvalidUsdtAddress();
    error InvalidThalAddress();
    error InvalidDefaultAdmin();
    error InvalidPresaleManager();
    error InvalidComplianceOfficer();
    error PresaleAlreadyStarted();
    error PresaleCannotStartInPast();
    error PresaleNotStarted();
    error PresaleNotActive();
    error PresaleClosed();
    error AmountTooSmall();
    error AmountTooLarge();
    error UserLimitExceeded();
    error InsufficientThalBalance();
    error InvalidVestingAddress();
    error InvalidRecipient();
    error AmountMustBePositive();
    error InsufficientUsdtBalance();

    error InsufficientTokenBalance();
    error VestingContractNotSet();

    IERC20 public immutable USDT_TOKEN;
    IERC20 public immutable THAL_TOKEN;

    // ========================================
    // STATE VARIABLES
    // ========================================

    uint256 public presaleStartTime;
    uint256 public presaleEndTime;

    uint256 public totalTokensSold;
    uint256 public totalUsdtRaised;

    // Purchase tracking
    mapping(address => uint256) public userPurchases; // USDT amount purchased
    mapping(address => uint256) public userAllocations; // THAL tokens allocated

    // Vesting integration
    address public vestingContract;

    // ========================================
    // EVENTS
    // ========================================

    event PresaleStarted(uint256 startTime, uint256 endTime);
    event TokensPurchased(
        address indexed buyer,
        uint256 usdtAmount,
        uint256 thalAmount,
        bytes32 vestingScheduleId
    );
    event PresaleEnded(uint256 totalTokensSold, uint256 totalUsdtRaised);
    event EmergencyPaused(address indexed pauser);
    event EmergencyUnpaused(address indexed unpauser);

    // ========================================
    // CONSTRUCTOR
    // ========================================

    /**
     * @dev Initialize presale contract
     * @param usdtTokenAddress USDT token contract address
     * @param thalTokenAddress THAL token contract address
     * @param defaultAdmin Default admin address
     * @param presaleManager Presale manager address
     * @param complianceOfficer Compliance officer address
     */
    constructor(
        address usdtTokenAddress,
        address thalTokenAddress,
        address defaultAdmin,
        address presaleManager,
        address complianceOfficer
    ) {
        if (usdtTokenAddress == address(0)) revert InvalidUsdtAddress();
        if (thalTokenAddress == address(0)) revert InvalidThalAddress();
        if (defaultAdmin == address(0)) revert InvalidDefaultAdmin();
        if (presaleManager == address(0)) revert InvalidPresaleManager();
        if (complianceOfficer == address(0)) revert InvalidComplianceOfficer();

        USDT_TOKEN = IERC20(usdtTokenAddress);
        THAL_TOKEN = IERC20(thalTokenAddress);

        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(PRESALE_MANAGER_ROLE, presaleManager);
        _grantRole(COMPLIANCE_ROLE, complianceOfficer);
    }

    // ========================================
    // EXTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Start presale
     * @param startTime Presale start timestamp (0 = now)
     */
    function startPresale(uint256 startTime)
        external
        onlyRole(PRESALE_MANAGER_ROLE)
    {
        if (presaleStartTime != 0) revert PresaleAlreadyStarted();

        uint256 actualStartTime = startTime == 0 ? block.timestamp : startTime;
        if (actualStartTime < block.timestamp) revert PresaleCannotStartInPast();

        presaleStartTime = actualStartTime;
        presaleEndTime = actualStartTime + PRESALE_DURATION;

        emit PresaleStarted(presaleStartTime, presaleEndTime);
    }

    /**
     * @dev Purchase tokens with USDT
     * @param usdtAmount Amount of USDT to spend
     *
     * Note: This function assumes off-chain validation has occurred
     * for KYC, purchase limits, and eligibility
     */
    function purchaseTokens(uint256 usdtAmount)
        external
        whenNotPaused
        nonReentrant
    {
        // Basic validation
        if (presaleStartTime == 0) revert PresaleNotStarted();
        if (block.timestamp < presaleStartTime) revert PresaleNotActive();
        if (block.timestamp > presaleEndTime) revert PresaleClosed();
        if (usdtAmount < MIN_PURCHASE) revert AmountTooSmall();
        if (usdtAmount > MAX_PURCHASE) revert AmountTooLarge();

        // Check user hasn't exceeded limits (off-chain validation assumed)
        if (userPurchases[msg.sender] + usdtAmount > MAX_PURCHASE) {
            revert UserLimitExceeded();
        }

        // Calculate THAL tokens (1 USDT = 100 THAL)
        // CRITICAL FIX: Properly convert from USDT (6 decimals) to THAL (18 decimals)
        // usdtAmount is in 6 decimals, need to convert to 18 decimals and multiply by 100
        uint256 thalAmount = (usdtAmount * 100 * 10**12); // Correct conversion: 6 decimals -> 18 decimals with 100x multiplier

        // Check contract has enough THAL tokens
        if (THAL_TOKEN.balanceOf(address(this)) < thalAmount) {
            revert InsufficientThalBalance();
        }

        // Transfer USDT from buyer
        USDT_TOKEN.safeTransferFrom(msg.sender, address(this), usdtAmount);

        // Update tracking
        userPurchases[msg.sender] += usdtAmount;
        userAllocations[msg.sender] += thalAmount;
        totalUsdtRaised += usdtAmount;
        totalTokensSold += thalAmount;

        // Create vesting schedule if vesting contract is set
        bytes32 vestingScheduleId = bytes32(0);
        if (vestingContract != address(0)) {
            vestingScheduleId = _createVestingSchedule(msg.sender, thalAmount);
        } else {
            // Direct transfer if no vesting
            THAL_TOKEN.safeTransfer(msg.sender, thalAmount);
        }

        emit TokensPurchased(msg.sender, usdtAmount, thalAmount, vestingScheduleId);
    }

    /**
     * @dev Set vesting contract address
     * @param vestingAddr Vesting contract address
     */
    function setVestingContract(address vestingAddr)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (vestingAddr == address(0)) revert InvalidVestingAddress();
        vestingContract = vestingAddr;
    }

    /**
     * @dev Withdraw collected USDT (only admin)
     * @param amount Amount to withdraw
     * @param recipient Recipient address
     */
    function withdrawUsdt(uint256 amount, address recipient)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
        nonReentrant
    {
        if (recipient == address(0)) revert InvalidRecipient();
        if (amount == 0) revert AmountMustBePositive();
        if (USDT_TOKEN.balanceOf(address(this)) < amount) revert InsufficientUsdtBalance();

        USDT_TOKEN.safeTransfer(recipient, amount);
    }

    /**
     * @dev Withdraw unsold THAL tokens (only admin)
     * @param amount Amount to withdraw
     * @param recipient Recipient address
     */
    function withdrawUnsoldTokens(uint256 amount, address recipient)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
        nonReentrant
    {
        if (recipient == address(0)) revert InvalidRecipient();
        if (amount == 0) revert AmountMustBePositive();
        if (THAL_TOKEN.balanceOf(address(this)) < amount) revert InsufficientTokenBalance();

        THAL_TOKEN.safeTransfer(recipient, amount);
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
        emit EmergencyPaused(msg.sender);
    }

    /**
     * @dev Emergency unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
        emit EmergencyUnpaused(msg.sender);
    }

    // ========================================
    // PUBLIC VIEW FUNCTIONS
    // ========================================

    function isPresaleActive() external view returns (bool) {
        return presaleStartTime > 0 &&
               block.timestamp >= presaleStartTime &&
               block.timestamp <= presaleEndTime;
    }

    /**
     * @dev Get presale status
     */
    function getPresaleStatus() external view returns (
        uint256 startTime,
        uint256 endTime,
        uint256 tokensSold,
        uint256 usdtRaised,
        bool isActive
    ) {
        return (
            presaleStartTime,
            presaleEndTime,
            totalTokensSold,
            totalUsdtRaised,
            this.isPresaleActive()
        );
    }

    /**
     * @dev Get user purchase info
     * @param user User address
     */
    function getUserPurchaseInfo(address user) external view returns (
        uint256 usdtPurchased,
        uint256 thalAllocated,
        uint256 remainingLimit
    ) {
        uint256 purchased = userPurchases[user];
        uint256 remaining = purchased >= MAX_PURCHASE ? 0 : MAX_PURCHASE - purchased;

        return (purchased, userAllocations[user], remaining);
    }

    /**
     * @dev Calculate THAL amount for USDT input
     * @param usdtAmount USDT amount in smallest units (6 decimals)
     * @return THAL amount in smallest units (18 decimals)
     */
    function calculateThalAmount(uint256 usdtAmount) external pure returns (uint256) {
        // 1 USDT (10^6 units) = 100 THAL (100 * 10^18 units)
        // So: usdtAmount * 100 * 10^12 = usdtAmount * 100 * 10^(18-6)
        return usdtAmount * 100 * 10**12;
    }

    // ========================================
    // INTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Create vesting schedule for purchased tokens
     * @param beneficiary Token recipient
     * @param amount THAL token amount
     * @return scheduleId Vesting schedule identifier
     */
    function _createVestingSchedule(address beneficiary, uint256 amount)
        internal
        returns (bytes32)
    {
        if (vestingContract == address(0)) revert VestingContractNotSet();

        // Call actual ThaliumVesting contract
        IThaliumVesting vesting = IThaliumVesting(vestingContract);

        // Create 90-day linear vesting with 30-day cliff
        // This matches the presale terms: tokens vest over 3 months
        bytes32 scheduleId = vesting.createVestingSchedule(
            beneficiary,           // Who receives the tokens
            amount,                // Total THAL amount
            block.timestamp,       // Start vesting immediately
            30 days,               // 30-day cliff period
            90 days,               // 90-day total vesting duration
            false,                 // Not revocable (presale purchases are final)
            "presale"              // Category identifier
        );

        return scheduleId;
    }
}

