// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {ERC20Votes} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import {Nonces} from "@openzeppelin/contracts/utils/Nonces.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ThaliumToken
 * @dev ERC20 token for the Thalium DeFi ecosystem
 *
 * This contract implements a secure ERC20 token with:
 * - Governance capabilities through ERC20Votes
 * - Gasless approvals via ERC20Permit
 * - Role-based access control for administrative functions
 * - Emergency pause functionality
 * - Reentrancy protection
 *
 * Security Model:
 * - On-chain: Core token operations and basic security
 * - Off-chain: Complex validation, KYC, and compliance checks
 *
 * @author Thalium Development Team
 */
contract ThaliumToken is ERC20, ERC20Permit, ERC20Votes, AccessControl, Pausable, ReentrancyGuard {
    // ========================================
    // CONSTANTS
    // ========================================

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18; // 1 billion tokens

    // ========================================
    // STATE VARIABLES
    // ========================================

    // Track total minted for supply control
    uint256 private _totalMinted;

    // ========================================
    // EVENTS
    // ========================================

    event TokensMinted(address indexed to, uint256 amount, address indexed minter);
    event TokensBurned(address indexed from, uint256 amount, address indexed burner);
    event EmergencyPaused(address indexed pauser);
    event EmergencyUnpaused(address indexed unpauser);

    error InvalidAddress();
    error InitialSupplyExceedsMaxSupply();
    error CannotMintToZeroAddress();
    error AmountMustBePositive();
    error MaxSupplyExceeded();
    error CannotBurnFromZeroAddress();
    error InsufficientBalance();

    // ========================================
    // CONSTRUCTOR
    // ========================================

    /**
     * @dev Initialize the Thalium token
     * @param defaultAdmin Address with DEFAULT_ADMIN_ROLE
     * @param minter Address with MINTER_ROLE
     * @param pauser Address with PAUSER_ROLE
     * @param burner Address with BURNER_ROLE
     * @param initialSupply Initial token supply to mint
     */
    constructor(
        address defaultAdmin,
        address minter,
        address pauser,
        address burner,
        uint256 initialSupply
    ) ERC20("Thalium", "THAL") ERC20Permit("Thalium") {
        if (defaultAdmin == address(0) || minter == address(0) || pauser == address(0) || burner == address(0)) {
            revert InvalidAddress();
        }

        // Grant roles
        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(MINTER_ROLE, minter);
        _grantRole(PAUSER_ROLE, pauser);
        _grantRole(BURNER_ROLE, burner);

        // Mint initial supply if specified
        if (initialSupply > 0) {
            if (initialSupply > MAX_SUPPLY) revert InitialSupplyExceedsMaxSupply();
            _mint(defaultAdmin, initialSupply);
            _totalMinted = initialSupply;
        }
    }

    // ========================================
    // EXTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Mint new tokens (only MINTER_ROLE)
     * @param to Recipient address
     * @param amount Amount to mint
     */
    function mint(address to, uint256 amount)
        external
        onlyRole(MINTER_ROLE)
        whenNotPaused
        nonReentrant
    {
        if (to == address(0)) revert CannotMintToZeroAddress();
        if (amount == 0) revert AmountMustBePositive();
        if (_totalMinted + amount > MAX_SUPPLY) revert MaxSupplyExceeded();

        _totalMinted += amount;
        _mint(to, amount);

        emit TokensMinted(to, amount, msg.sender);
    }

    /**
     * @dev Burn tokens (only BURNER_ROLE)
     * @param from Address to burn from
     * @param amount Amount to burn
     */
    function burn(address from, uint256 amount)
        external
        onlyRole(BURNER_ROLE)
        whenNotPaused
        nonReentrant
    {
        if (from == address(0)) revert CannotBurnFromZeroAddress();
        if (amount == 0) revert AmountMustBePositive();
        if (balanceOf(from) < amount) revert InsufficientBalance();

        _burn(from, amount);

        emit TokensBurned(from, amount, msg.sender);
    }

    /**
     * @dev Emergency pause (only PAUSER_ROLE)
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit EmergencyPaused(msg.sender);
    }

    /**
     * @dev Emergency unpause (only DEFAULT_ADMIN_ROLE)
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
        emit EmergencyUnpaused(msg.sender);
    }

    /**
     * @dev Override transfer with pause check
     */
    function transfer(address to, uint256 amount)
        public
        override
        whenNotPaused
        returns (bool)
    {
        return super.transfer(to, amount);
    }

    /**
     * @dev Override transferFrom with pause check
     */
    function transferFrom(address from, address to, uint256 amount)
        public
        override
        whenNotPaused
        returns (bool)
    {
        return super.transferFrom(from, to, amount);
    }

    /**
     * @dev Override nonces for ERC20Permit
     */
    function nonces(address owner)
        public
        view
        override(ERC20Permit, Nonces)
        returns (uint256)
    {
        return super.nonces(owner);
    }

    /**
     * @dev Override _update for ERC20Votes
     */
    function _update(address from, address to, uint256 value)
        internal
        override(ERC20, ERC20Votes)
    {
        super._update(from, to, value);
    }

    /**
     * @dev Get remaining mintable supply
     */
    function remainingSupply() external view returns (uint256) {
        return MAX_SUPPLY - _totalMinted;
    }

    /**
     * @dev Total minted supply so far
     */
    function totalMinted() external view returns (uint256) {
        return _totalMinted;
    }

}

contracts/ThaliumVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title ThaliumVesting
 * @dev Token vesting contract for the Thalium ecosystem
 *
 * This contract manages token vesting schedules with:
 * - Streamlined vesting logic
 * - Off-chain validation for complex rules
 * - Emergency controls
 * - Gas-efficient operations
 *
 * Security Model:
 * - On-chain: Basic vesting calculations and token releases
 * - Off-chain: Eligibility validation, compliance checks
 *
 * @author Thalium Development Team
 */
contract ThaliumVesting is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Math for uint256;

    struct VestingSchedule {
        address beneficiary;
        uint256 totalAmount;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        uint256 releasedAmount;
        uint256 lastClaimTime;
        bool revocable;
        bool revoked;
        bytes32 category; // Category identifier
    }

    error InvalidTokenAddress();
    error InvalidDefaultAdmin();
    error InvalidVestingManager();
    error InvalidComplianceOfficer();
    error InvalidBeneficiary();
    error AmountMustBePositive();
    error VestingDurationTooShort();
    error VestingDurationTooLong();
    error CliffExceedsDuration();
    error CannotBackdateSchedule();
    error StartTimeTooFarInFuture();
    error InsufficientContractBalance();
    error ScheduleIdCollision();
    error NotAuthorized();
    error ScheduleRevoked();
    error AllTokensReleased();
    error ClaimCooldownActive();
    error ScheduleNotFound();
    error ScheduleNotRevocable();
    error ScheduleAlreadyRevoked();
    error NoTokensToRelease();

    bytes32 public constant VESTING_MANAGER_ROLE = keccak256("VESTING_MANAGER_ROLE");
    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");

    uint256 public constant MAX_VESTING_DURATION = 4 * 365 days;
    uint256 public constant MIN_VESTING_DURATION = 30 days;
    uint256 public constant CLAIM_COOLDOWN = 24 hours;

    // ========================================
    // CONSTANTS
    // ========================================

    // ========================================
    // STATE VARIABLES
    // ========================================

    IERC20 public immutable THAL_TOKEN;

    mapping(bytes32 => VestingSchedule) public vestingSchedules;
    mapping(address => bytes32[]) public beneficiarySchedules;

    uint256 public totalSchedules;
    uint256 public totalCommittedTokens;

    // ========================================
    // EVENTS
    // ========================================

    event VestingScheduleCreated(
        bytes32 indexed scheduleId,
        address indexed beneficiary,
        uint256 totalAmount,
        bytes32 category
    );

    event TokensReleased(
        bytes32 indexed scheduleId,
        address indexed beneficiary,
        uint256 amount
    );

    event VestingScheduleRevoked(
        bytes32 indexed scheduleId,
        address indexed beneficiary,
        uint256 unvestedAmount
    );

    event EmergencyPaused(address indexed pauser);
    event EmergencyUnpaused(address indexed unpauser);

    // ========================================
    // CONSTRUCTOR
    // ========================================

    /**
     * @dev Initialize vesting contract
     * @param thalTokenAddress THAL token contract address
     * @param defaultAdmin Default admin address
     * @param vestingManager Vesting manager address
     * @param complianceOfficer Compliance officer address
     */
    constructor(
        address thalTokenAddress,
        address defaultAdmin,
        address vestingManager,
        address complianceOfficer
    ) {
        if (thalTokenAddress == address(0)) revert InvalidTokenAddress();
        if (defaultAdmin == address(0)) revert InvalidDefaultAdmin();
        if (vestingManager == address(0)) revert InvalidVestingManager();
        if (complianceOfficer == address(0)) revert InvalidComplianceOfficer();

        THAL_TOKEN = IERC20(thalTokenAddress);

        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(VESTING_MANAGER_ROLE, vestingManager);
        _grantRole(COMPLIANCE_ROLE, complianceOfficer);
    }

    // ========================================
    // EXTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Create vesting schedule
     * @param beneficiary Recipient address
     * @param totalAmount Total tokens to vest
     * @param startTime Vesting start time
     * @param cliffDuration Cliff period
     * @param vestingDuration Total vesting duration
     * @param revocable Whether schedule can be revoked
     * @param category Vesting category
     * @return scheduleId Unique schedule identifier
     */
    function createVestingSchedule(
        address beneficiary,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration,
        bool revocable,
        bytes32 category
    )
        external
        onlyRole(VESTING_MANAGER_ROLE)
        whenNotPaused
        returns (bytes32)
    {
        // Basic validation
        if (beneficiary == address(0)) revert InvalidBeneficiary();
        if (totalAmount == 0) revert AmountMustBePositive();
        if (vestingDuration < MIN_VESTING_DURATION) revert VestingDurationTooShort();
        if (vestingDuration > MAX_VESTING_DURATION) revert VestingDurationTooLong();
        if (vestingDuration < cliffDuration) revert CliffExceedsDuration();

        // Start time validation
        uint256 actualStartTime = startTime == 0 ? block.timestamp : startTime;
        if (actualStartTime < block.timestamp) revert CannotBackdateSchedule();
        if (actualStartTime > block.timestamp + 365 days) revert StartTimeTooFarInFuture();

        // Contract balance check
        if (THAL_TOKEN.balanceOf(address(this)) < totalCommittedTokens + totalAmount) {
            revert InsufficientContractBalance();
        }

        // Generate unique schedule ID
        bytes32 scheduleId = keccak256(
            abi.encodePacked(
                beneficiary,
                totalAmount,
                actualStartTime,
                block.timestamp,
                totalSchedules
            )
        );

        if (vestingSchedules[scheduleId].beneficiary != address(0)) {
            revert ScheduleIdCollision();
        }

        // Create vesting schedule
        vestingSchedules[scheduleId] = VestingSchedule({
            beneficiary: beneficiary,
            totalAmount: totalAmount,
            startTime: actualStartTime,
            cliffDuration: cliffDuration,
            vestingDuration: vestingDuration,
            releasedAmount: 0,
            lastClaimTime: 0,
            revocable: revocable,
            revoked: false,
            category: category
        });

        // Update tracking
        beneficiarySchedules[beneficiary].push(scheduleId);
        totalCommittedTokens += totalAmount;
        totalSchedules++;

        emit VestingScheduleCreated(scheduleId, beneficiary, totalAmount, category);
        return scheduleId;
    }

    /**
     * @dev Release vested tokens
     * @param scheduleId Vesting schedule ID
     */
    function releaseVestedTokens(bytes32 scheduleId)
        external
        whenNotPaused
        nonReentrant
    {
        VestingSchedule storage schedule = vestingSchedules[scheduleId];

        // Basic validation
        if (schedule.beneficiary != msg.sender) revert NotAuthorized();
        if (schedule.revoked) revert ScheduleRevoked();
        if (schedule.totalAmount <= schedule.releasedAmount) revert AllTokensReleased();

        // Cooldown check
        if (block.timestamp < schedule.lastClaimTime + CLAIM_COOLDOWN) {
            revert ClaimCooldownActive();
        }

        // Calculate releasable amount
        uint256 releasableAmount = _calculateReleasableAmount(scheduleId);
        if (releasableAmount == 0) revert NoTokensToRelease();

        // Update schedule
        schedule.releasedAmount += releasableAmount;
        schedule.lastClaimTime = block.timestamp;

        // Transfer tokens
        THAL_TOKEN.safeTransfer(msg.sender, releasableAmount);

        emit TokensReleased(scheduleId, msg.sender, releasableAmount);
    }

    /**
     * @dev Revoke vesting schedule
     * @param scheduleId Schedule to revoke
     */
    function revokeVestingSchedule(bytes32 scheduleId)
        external
        onlyRole(VESTING_MANAGER_ROLE)
        whenNotPaused
        nonReentrant
    {
        VestingSchedule storage schedule = vestingSchedules[scheduleId];

        if (schedule.beneficiary == address(0)) revert ScheduleNotFound();
        if (!schedule.revocable) revert ScheduleNotRevocable();
        if (schedule.revoked) revert ScheduleAlreadyRevoked();

        // Calculate unvested amount
        uint256 timeElapsed = block.timestamp - schedule.startTime;
        uint256 vestedAmount;

        if (timeElapsed >= schedule.vestingDuration) {
            vestedAmount = schedule.totalAmount;
        } else if (timeElapsed >= schedule.cliffDuration) {
            vestedAmount = Math.mulDiv(
                schedule.totalAmount,
                timeElapsed,
                schedule.vestingDuration
            );
        }

        uint256 unvestedAmount = schedule.totalAmount - vestedAmount;

        // Mark as revoked
        schedule.revoked = true;

        // Return unvested tokens to contract owner (off-chain decision)
        if (unvestedAmount > 0) {
            totalCommittedTokens -= unvestedAmount;
        }

        emit VestingScheduleRevoked(scheduleId, schedule.beneficiary, unvestedAmount);
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
        emit EmergencyPaused(msg.sender);
    }

    /**
     * @dev Emergency unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
        emit EmergencyUnpaused(msg.sender);
    }

    // ========================================
    // PUBLIC VIEW FUNCTIONS
    // ========================================

    /**
     * @dev Get releasable amount for schedule
     * @param scheduleId Vesting schedule ID
     */
    function getReleasableAmount(bytes32 scheduleId) external view returns (uint256) {
        return _calculateReleasableAmount(scheduleId);
    }

    /**
     * @dev Get beneficiary schedules with pagination
     * @param beneficiary User address
     * @param offset Starting index
     * @param limit Maximum results
     */
    function getBeneficiarySchedules(
        address beneficiary,
        uint256 offset,
        uint256 limit
    ) external view returns (bytes32[] memory) {
        bytes32[] storage userSchedules = beneficiarySchedules[beneficiary];
        uint256 userTotalSchedules = userSchedules.length;

        if (offset >= userTotalSchedules) {
            return new bytes32[](0);
        }

        uint256 endIndex = offset + limit;
        if (endIndex > userTotalSchedules) {
            endIndex = userTotalSchedules;
        }

        uint256 resultLength = endIndex - offset;
        bytes32[] memory result = new bytes32[](resultLength);

        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = userSchedules[offset + i];
        }

        return result;
    }

    /**
     * @dev Get vesting schedule details
     * @param scheduleId Schedule ID
     */
    function getVestingSchedule(bytes32 scheduleId)
        external
        view
        returns (
            address beneficiary,
            uint256 totalAmount,
            uint256 startTime,
            uint256 cliffDuration,
            uint256 vestingDuration,
            uint256 releasedAmount,
            uint256 lastClaimTime,
            bool revocable,
            bool revoked,
            bytes32 category
        )
    {
        VestingSchedule memory schedule = vestingSchedules[scheduleId];
        return (
            schedule.beneficiary,
            schedule.totalAmount,
            schedule.startTime,
            schedule.cliffDuration,
            schedule.vestingDuration,
            schedule.releasedAmount,
            schedule.lastClaimTime,
            schedule.revocable,
            schedule.revoked,
            schedule.category
        );
    }

    // ========================================
    // INTERNAL FUNCTIONS
    // ========================================

    /**
     * @dev Calculate releasable amount
     * @param scheduleId Vesting schedule ID
     */
    function _calculateReleasableAmount(bytes32 scheduleId)
        internal
        view
        returns (uint256)
    {
        VestingSchedule memory schedule = vestingSchedules[scheduleId];

        if (schedule.revoked || block.timestamp < schedule.startTime + schedule.cliffDuration) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - schedule.startTime;

        if (timeElapsed >= schedule.vestingDuration) {
            return schedule.totalAmount - schedule.releasedAmount;
        }

        uint256 vestedAmount = Math.mulDiv(
            schedule.totalAmount,
            timeElapsed,
            schedule.vestingDuration
        );

        return vestedAmount - schedule.releasedAmount;
    }
}

